effect.script:
function animate(env,el,p) {
    let groups = [];
    groups.push(0);
    el.shaderGroups = groups;
    return el;
}

effect.shader:

vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
#define fragCoord gl_FragCoord.xy

//////////////////////////
    #define PI 3.141593
    #define DtR 0.01745

    vec3 rgb2hsv(vec3 c)
    {
        vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
        vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
        vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));

        float d = q.x - min(q.w, q.y);
        float e = 1.0e-10;
        return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
    }

    // From iq - https://www.shadertoy.com/view/MsS3Wc
    vec3 hsv2rgb_smooth( in vec3 c )
    {
        vec3 rgb = clamp( abs(mod(c.x*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0, 0.0, 1.0 );

    	rgb = rgb*rgb*(3.0-2.0*rgb); // cubic smoothing	

    	return c.z * mix( vec3(1.0), rgb, c.y);
    }

    float tunnel(vec3 p)
    {
        p.z+= autop? PROGRESS + (acTime*SPEED) : PROGRESS;
        p.xy+=sin(p.z)*0.5+sin(p.xz*12.0)*0.05+sin(p.zy*20.0)*0.025;
        return 1.0-length(p.xy);
    }

    float map(vec3 p)
    {
        return tunnel(p);
    }
//////////////////////////
    void main() {
    if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
    vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
    vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

    vec2 image_size = getTexSize(inputImg.size);
    vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
    vec2 iMouse = vec2(0.5, 0.5);
    float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;

    vec2 TanRyu;
    // TanRyu = acScreenNorm; 
    TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
    TanRyu.y*=acLayerSize.y/acLayerSize.x;

    TanRyu /= scale;
    TanRyu *= rot2m((0.0+angle)*0.0174533);
    TanRyu += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.0)/500.;
    vec2 scaleVec;
    scaleVec = vec2(scale*stretch.x,scale*stretch.y);
    TanRyu /= scaleVec;

    /////////////////////////

	vec4 fragColor;

        vec2 uv = TanRyu;

        vec3 cz = normalize(vec3(0,0,1));
        vec3 cx = normalize(cross(cz,vec3(0,1,0)));
        vec3 cy = normalize(cross(cx,cz));

        vec3 z = vec3(cx*uv.x + cy*uv.y + cz*0.15);
        vec3 pos = vec3(0);

        float d = 0.;
        float att = 0.;

        // for(int i = 0; i < 64; ++i)
        for(int i = 0; i < 256; ++i)
        {
            d=map(pos);
            if(d < .0001) break;
            if(d > 10000.0)break;
            pos+= z * d;
            att+=0.2/(abs(d)+0.2);
        }

        vec3 color = rgb2hsv(vec3(0.75,0.2,0.10));
        // color = COLORS.rgb;

        color.r=pos.z*0.01+sin(-iTime*0.05);
        color = hsv2rgb_smooth(color);

        if(d < 10000.0)
        {
            color *= 0.3 + att*0.006;
        }

       	//color=pow(color,vec3(0.4545));
        color*=1.0-length(uv);

        fragColor = vec4(color,1.0);

        float hardness = HRD;
	    vec4 factor = mix(texColorX,fragColor,1.0);
	    const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
        float luminance = dot(fragColor.rgb, luminanceWeighting);
        vec4 gradmap = mix(color1,color2,luminance)*fragColor.a;
	    if(GRADMAP) { 
	    hardness += 2.0;
	    factor = mix(texColorX,gradmap,1.0);
	     }

	    // vec4 xbuffer = texture2DCv(buff1.texture, acScreenNorm.st);

    vec4 resultfinal;
      if( blendMode==0 ) { resultfinal = (factor * hardness) * texColor.a; }
      else if( blendMode==1 ) { factor *= hardness;
        vec4 c = factor + vec4(1.0)*(1.0-factor.a);
        resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
        // resultfinal = min(factor, texColor) * texColor.a; }
      else if( blendMode==2 ) { factor *= hardness; 
        resultfinal = vec4( 1.0-((1.0-(texColor.rgb/texColor.a))*(1.0-factor.rgb)),1.0) * texColor.a; }
          // resultfinal = max(factor, texColor) * texColor.a; }

	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
      }
    }
